head.script:
scwin.onpageload = function() {
    scwin.createWindow();
    var windowIdArr = [];
    for (i = 0; i < windowContainer1.windows.length; i++) {
        windowIdArr.push(windowContainer1.windows[i].windowId);
    }
    windowContainer1.setArrangeWindows("vertical", windowIdArr);
};
scwin.onpageunload = function() {};
scwin.createWindow = function() {
    var c_cnt = 3;
    var c_subName = "sub";
    var c_menuName = "menu";
    for (var i = 0; i < c_cnt; i++) {
        var winObj = {
            title: c_subName + i,
            src: "sub.xml",
            windowId: c_menuName + i
        }
        windowContainer1.createWindow(winObj);
    }
};
scwin.trigger1_onclick = function() {
    var idStr = windowContainer1.windows[windowContainer1.getSelectedIndex()].id;
    input1.setValue(idStr);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_subWindow_menu0_1').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#windowContainer1_subWindow_menu0_1').hasClass('w2window_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
